parameters.jsCode:
const url = $('子流程觸發').item.json.url;
let realUrl = url;
try {
  const match = url.match(/articles\/([^?]+)/);
  if (match) {
    const decoded = Buffer.from(match[1], 'base64').toString('utf-8');
    const urlMatch = decoded.match(/https?:\/\/[^\s"<>]+/);
    if (urlMatch) realUrl = urlMatch[0];
  }
} catch(e) {
  realUrl = url;
}
return [{
  json: {
    ...$input.item.json,
    realUrl: realUrl
  }
}];

const html = $json.data || '';
const articleMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
let text = articleMatch ? articleMatch[1] : html;
text = text.replace(/<script[\s\S]*?<\/script>/gi, '');
text = text.replace(/<style[\s\S]*?<\/style>/gi, '');
text = text.replace(/<nav[\s\S]*?<\/nav>/gi, '');
text = text.replace(
  /<figure[^>]*>[\s\S]*?<img[^>]*src="([^"]*)"[^>]*>[\s\S]*?<figcaption[^>]*>([\s\S]*?)<\/figcaption>[\s\S]*?<\/figure>/gi,
  '\n[IMAGE:$1|CAPTION:$2]\n'
);
text = text.replace(
  /<figure[^>]*>[\s\S]*?<img[^>]*src="([^"]*)"[^>]*>[\s\S]*?<\/figure>/gi,
  '\n[IMAGE:$1|CAPTION:]\n'
);
text = text.replace(/<\/p>/gi, '\n\n');
text = text.replace(/<[^>]+>/g, '');
text = text.replace(/\r\n/g, '\n');
text = text.replace(/\n{3,}/g, '\n\n');
text = text.replace(/[ \t]{2,}/g, ' ');
text = text.trim();
return [{
  json: {
    ...$input.item.json,
    data: text
  }
}];

const raw = $json.content.parts[0].text;
const parsed = JSON.parse(raw);
const generateImage = $('子流程觸發').item.json.generateImage === 'true';

let content = '';
content += `<!-- wp:paragraph -->\n<p><strong>${parsed.author}</strong></p>\n<!-- /wp:paragraph -->\n\n`;

for (const section of parsed.sections) {
  if (section.imageUrl) {
    content += `<!-- wp:image -->\n<figure class="wp-block-image"><img src="${section.imageUrl}" alt="${section.imageCaption || ''}"/>${section.imageCaption ? `<figcaption class="wp-element-caption">${section.imageCaption}</figcaption>` : ''}</figure>\n<!-- /wp:image -->\n\n`;
  }
  if (section.heading && section.heading.trim() !== '') {
    content += `<!-- wp:heading {"level":3} -->\n<h3 style="font-size:18px;color:#000000;font-family:Arial;">${section.heading}</h3>\n<!-- /wp:heading -->\n\n`;
  }
  if (section.content && section.content.trim() !== '') {
    const subParagraphs = section.content.split(/\n+/).filter(p => p.trim() !== '');
    for (const para of subParagraphs) {
      content += `<!-- wp:paragraph -->\n<p style="font-size:18px;color:#000000;font-family:Arial;">${para.trim()}</p>\n<!-- /wp:paragraph -->\n\n`;
    }
  }
}

content = `<!-- wp:html -->\n<div class="auto-draft">\n<!-- /wp:html -->\n\n` + content;
content += `<!-- wp:separator -->\n<hr class="wp-block-separator"/>\n<!-- /wp:separator -->\n\n`;
content += `<!-- wp:heading {"level":5} -->\n<h5><em>【參考資料】</em></h5>\n<!-- /wp:heading -->\n\n`;
content += `<!-- wp:paragraph -->\n<p style=\"font-size:16px;color:#000000;font-family:Arial;\"><em>${parsed.reference}</em></p>\n<!-- /wp:paragraph -->\n\n`;
content += `<!-- wp:html -->\n</div>\n<!-- /wp:html -->\n`;

// 分類 ID 對應表，請依照你的 WordPress 設定調整
const categoryMap = {
  'CATEGORY_A': 'YOUR_CATEGORY_ID',
  'CATEGORY_B': 'YOUR_CATEGORY_ID',
  'CATEGORY_C': 'YOUR_CATEGORY_ID'
};

const categoryName = $('子流程觸發').item.json.category || 'CATEGORY_A';
const categoryId = categoryMap[categoryName] || 'YOUR_DEFAULT_CATEGORY_ID';

return [{
  json: {
    title: parsed.title,
    generateImage: generateImage,
    content: content,
    excerpt: parsed.seoDescription,
    seoTitle: parsed.seoTitle,
    seoDescription: parsed.seoDescription,
    slug: parsed.slug,
    tags: parsed.tags || [],
    imagePrompt: parsed.imagePrompt,
    categoryId: categoryId,
    wpUserId: 'YOUR_WP_USER_ID',
    notifyEmail: 'YOUR_EMAIL',
    origTitle: $('子流程觸發').item.json.title,
    origUrl: $('子流程觸發').item.json.url
  }
}];

const tagIds = $json.tagIds || [];
const articleData = $('組合內文與資料').item.json;
return [{
  json: {
    ...articleData,
    tagIds: tagIds
  }
}];

