parameters.jsCode:
const response = $json;
const parts = response.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => p.inlineData);
if (!imagePart) throw new Error('No image generated');
const base64Data = imagePart.inlineData.data;
const mimeType = imagePart.inlineData.mimeType || 'image/jpeg';
return [{
  json: { ...$('合併文章與標籤').item.json },
  binary: {
    imageData: {
      data: base64Data,
      mimeType: mimeType,
      fileName: 'cover.jpg',
      fileExtension: 'jpg'
    }
  }
}];

return [{
  json: {
    postId: $json.id,
    focuskw: $('合併文章與標籤').item.json.tags?.[0] || '',
    metadesc: $('合併文章與標籤').item.json.seoDescription || '',
    title: $('合併文章與標籤').item.json.title,
    notifyEmail: $('合併文章與標籤').item.json.notifyEmail,
    origTitle: $('合併文章與標籤').item.json.origTitle,
    origUrl: $('合併文章與標籤').item.json.origUrl,
    category: $('子流程觸發').item.json.category
  }
}];
